use super::*;
use crate::money::{sum, Currency, Money};

/// Every source's monthly equivalent, together.
pub fn expected_monthly(a: &IncomeAnalysis, currency: Currency) -> Result<Money, crate::money::CurrencyMismatch> {
    let each: Vec<Money> = a.sources.iter().map(|s| s.monthly_equivalent).collect();
    sum(&each, currency)
}
